import {variants,dial,gameAngles,timeAngles} from './clock.mjs';
const $=s=>document.querySelector(s);let selected='AB',mode='game';
$('#concepts').innerHTML=Object.entries(variants).map(([id,v])=>`<article class="concept"><a href="assets/concept-${id}.png" target="_blank"><div class="image-stage"><img src="assets/concept-${id}.png" alt="${id} ${v.name} 完成イメージ" loading="lazy"></div></a><div class="concept-copy"><span class="letter">${id}</span><div><h3>${v.name}</h3><p>${v.copy}</p><button type="button" data-try="${id}">この案の針を試す ↗</button></div></div></article>`).join('');
$('#variant-buttons').innerHTML=Object.keys(variants).map(id=>`<button type="button" data-variant="${id}" aria-pressed="${id===selected}">${id}</button>`).join('');
function render(){const r=+$('#round').value,a=+$('#a').value,b=+$('#b').value;let angles=gameAngles(r,a,b);if(mode==='clock'){const [h,m,s=0]=$('#time').value.split(':').map(Number);angles=timeAngles(h||0,m||0,s||0);}const opts={palette:$('#palette').value,angles,mode};$('#live-dial').innerHTML=dial(selected,{...opts,uid:'live'});$('#precise-grid').innerHTML=Object.entries(variants).map(([id,v])=>`<figure>${dial(id,{...opts,uid:'grid-'+id})}<figcaption>${id} · ${v.name}</figcaption></figure>`).join('');['round','a','b'].forEach(id=>$('#'+id+'-out').value=$('#'+id).value);$('#status').textContent=mode==='game'?`ラウンド ${r} / そだち A ${a} · B ${b}`:`通常時計 ${$('#time').value}`;document.querySelectorAll('[data-variant]').forEach(el=>{if(el.tagName==='BUTTON')el.setAttribute('aria-pressed',String(el.dataset.variant===selected));});document.querySelectorAll('[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.mode===mode)));$('#game-controls').hidden=mode!=='game';$('#clock-controls').hidden=mode!=='clock';}
document.addEventListener('click',e=>{const v=e.target.closest('button[data-variant],button[data-try]');if(v){selected=v.dataset.variant||v.dataset.try;render();if(v.dataset.try)$('#play').scrollIntoView({behavior:'smooth'});}const m=e.target.closest('[data-mode]');if(m){mode=m.dataset.mode;render();}});
['round','a','b','palette','time'].forEach(id=>$('#'+id).addEventListener('input',render));$('#overlap').onclick=()=>{$('#round').value=10;$('#a').value=100;$('#b').value=100;render();};$('#reset').onclick=()=>{$('#round').value=7;$('#a').value=40;$('#b').value=20;render();};render();
